function cleanHeaderSocials() {
  const contacts = document.querySelector('header [code-path="src/components/Layout.tsx:58:11"]');
  if (!contacts) return;
  contacts.querySelectorAll(":scope > a").forEach((link) => {
    const href = link.getAttribute("href") || "";
    if (/wa\.me|vk\.com|instagram\.com|t\.me/i.test(href)) link.remove();
  });
  const email = contacts.querySelector('a[href^="mailto:"]');
  if (email) {
    let node = contacts.firstElementChild;
    while (node && node !== email) {
      const next = node.nextElementSibling;
      if (node.tagName === "SPAN") node.remove();
      node = next;
    }
  }
}

