function alignProductDescriptions() {
  document.querySelectorAll('[data-product-description]').forEach((description) => {
    const page = description.closest('[code-path="src/pages/ProductPage.tsx:47:5"]');
    const gallery = page?.querySelector('[code-path="src/pages/ProductPage.tsx:58:9"]');
    if (!gallery) return;
    description.style.removeProperty("margin-top");
    // The gallery column stretches to the height of the product details grid.
    // Measure the actual image/thumbnail content instead of that stretched
    // column, otherwise the description gets pushed far below the gallery.
    const contentParts = [
      gallery.querySelector('[code-path="src/pages/ProductPage.tsx:59:11"]'),
      gallery.querySelector('[code-path="src/pages/ProductPage.tsx:65:13"]'),
    ].filter(Boolean);
    const galleryBottom = contentParts.reduce((bottom, part) => {
      return Math.max(bottom, part.getBoundingClientRect().bottom);
    }, gallery.getBoundingClientRect().top);
    const overlap = galleryBottom + 32 - description.getBoundingClientRect().top;
    if (overlap > 0) {
      const baseMargin = Number.parseFloat(description.dataset.productDescriptionBaseMargin || "0") || 0;
      description.style.marginTop = `${Math.ceil(baseMargin + overlap)}px`;
    }
  });
}

